-- ffi.lua : fnmatch.ffi, typed access to an executable's functions and classes through the
-- LuaJIT FFI, from a module of declarations generated by `stellar-fnmatch cdef` (from the PDB of
-- the build).
--
-- Embedded into the fnmatch module at build time and run by luaopen_fnmatch with the module
-- table as its argument (it becomes fnmatch.ffi). It also works on its own:
-- `local fnffi = dofile("ffi.lua")` returns the same table.
--
--   local b = fnmatch.ffi.load("gog-4.5.2.ffi.lua")      -- or the module's table
--   local CNamedColor = b:type("CNamedColor")              -- a ctype, declared with what it needs
--   local f = b:fn("CShip::CalcRegenAmount", address)      -- a typed function pointer
--   local ok = b:vcall(object, "CTextLexer::GetTok")       -- a virtual call through the vtable
--
-- Without the LuaJIT FFI (Lua 5.1 to 5.4) the module loads, `available` is false, and every
-- function that needs the FFI raises an error that says so.

local fnmatch = ...
if type(fnmatch) ~= "table" then
    fnmatch = nil -- loaded on its own (dofile / require)
end

local M = {}

local has_ffi, ffi = pcall(require, "ffi")
has_ffi = has_ffi and type(ffi) == "table" and type(ffi.cdef) == "function"
if not has_ffi then
    ffi = nil
end
local has_jit, jit = pcall(require, "jit")
if not has_jit then
    jit = nil
end

M.available = has_ffi
M.format = 1

local function fail(message, level)
    error("fnmatch.ffi: " .. message, (level or 1) + 1)
end

local function need_ffi(level)
    if not has_ffi then
        fail("the LuaJIT FFI is not available in " .. tostring(_VERSION) .. ": typed functions and classes need LuaJIT", (level or 1) + 1)
    end
end

-- C names declared in this Lua state (one FFI state per Lua state), by the module that declared
-- them: two modules that define the same name differently cannot both be used.
local declared = {}

local bindings = {}
bindings.__index = bindings

-- fnmatch.ffi.load(source [, options]) -> bindings
--   source: the path of a generated module, or the table it returns
--   options.protect: wrap the functions that may throw (see bindings:fn)
function M.load(source, options)
    need_ffi(2)
    local mod = source
    if type(source) == "string" then
        local chunk, err = loadfile(source)
        if chunk == nil then
            return nil, "fnmatch.ffi: " .. tostring(err)
        end
        mod = chunk()
    end
    if type(mod) ~= "table" or type(mod.types) ~= "table" or type(mod.functions) ~= "table" then
        fail("not a module generated by stellar-fnmatch cdef", 2)
    end
    if mod.format ~= M.format then
        fail(string.format("module format %s, this runtime reads format %d", tostring(mod.format), M.format), 2)
    end
    if mod.abi ~= "msvc-x64" then
        fail("module for ABI " .. tostring(mod.abi) .. ", not msvc-x64", 2)
    end
    if options ~= nil and type(options) ~= "table" then
        fail("options must be a table", 2)
    end
    local key = mod.pdb and (tostring(mod.pdb.guid) .. "/" .. tostring(mod.pdb.age)) or tostring(mod)
    return setmetatable({
        module = mod,
        build = mod.build,
        _key = key,
        _options = options or {},
        _ctypes = {},     -- function declaration -> ctype
        _fns = {},        -- name -> chosen declaration (memo)
    }, bindings)
end

-- The C name of a type given by C name or C++ name.
function bindings:cname(name)
    local mod = self.module
    if mod.types[name] or mod.opaque[name] then
        return name
    end
    local c = mod.names[name]
    if type(c) == "table" then
        fail(string.format("%s names %d types (%s): use a C name", name, #c, table.concat(c, ", ")), 2)
    end
    return c
end

-- A batch of declarations: their text, and the state each type reaches once ffi.cdef accepts
-- the text (only then is it recorded in `declared`).
local function batch()
    return { text = {}, state = {} }
end

local function state_of(self, out, c)
    local d = out.state[c] or declared[c]
    if d ~= nil and d.key ~= self._key then
        fail(string.format("type %s is already declared by another module (pdb %s)", c, d.key), 4)
    end
    return d and d.how
end

-- Adds what type `c` needs (complete, or as an opaque struct) to the batch.
local function collect(self, c, complete, out, depth)
    if depth > 400 then
        fail("type dependencies too deep at " .. c, 3)
    end
    local mod = self.module
    local how = state_of(self, out, c)
    local t = mod.types[c]
    if t == nil then
        local o = mod.opaque[c]
        if o == nil then
            fail("unknown type " .. tostring(c), 3)
        end
        if complete then
            fail(string.format("type %s (%s) has no definition in this module: generate it with --classes", c, o.cpp), 3)
        end
        if how == nil then
            out.text[#out.text + 1] = string.format("%s %s; typedef %s %s %s;", o.kind, c, o.kind, c, c)
            out.state[c] = { key = self._key, how = "opaque" }
        end
        return
    end
    if t.kind == "enum" then
        if how == nil then
            out.text[#out.text + 1] = t.cdef
            out.state[c] = { key = self._key, how = "complete" }
        end
        return
    end
    if how == nil then
        out.text[#out.text + 1] = string.format("%s %s; typedef %s %s %s;", t.kind, c, t.kind, c, c)
        how = "opaque"
        out.state[c] = { key = self._key, how = how }
    end
    if complete and how == "opaque" then
        -- marked before the dependencies: a pointer back to it needs nothing more
        out.state[c] = { key = self._key, how = "complete" }
        for _, dep in ipairs(t.deps) do
            collect(self, dep, true, out, depth + 1)
        end
        for _, r in ipairs(t.refs) do
            collect(self, r, false, out, depth + 1)
        end
        out.text[#out.text + 1] = t.cdef
    end
end

local function flush(out)
    if #out.text > 0 then
        ffi.cdef(table.concat(out.text, "\n"))
    end
    for c, d in pairs(out.state) do
        declared[c] = d
    end
end

-- bindings:declare(name [, complete]) -> C name: declares a type (complete by default, with
-- every type it needs; or only as an opaque struct)
function bindings:declare(name, complete)
    need_ffi(2)
    local c = self:cname(name)
    if c == nil then
        fail("unknown type " .. tostring(name), 2)
    end
    local out = batch()
    collect(self, c, complete ~= false, out, 0)
    flush(out)
    return c
end

-- bindings:type(name) -> the ctype of a class, struct, union or enum (by C or C++ name)
function bindings:type(name)
    return ffi.typeof(self:declare(name))
end

-- bindings:ptr(name) -> the ctype of a pointer to it (opaque is enough)
function bindings:ptr(name)
    return ffi.typeof(self:declare(name, false) .. " *")
end

-- Metadata of a type: size, align, fields, bases, vfptrs, values (enums), cpp, cdef
function bindings:info(name)
    local c = self:cname(name)
    return c and (self.module.types[c] or self.module.opaque[c])
end

-- bindings:enum(name) -> { NAME = value, ... } plus the reverse (value -> NAME)
function bindings:enum(name)
    local t = self:info(name)
    if t == nil or t.kind ~= "enum" then
        fail(tostring(name) .. " is not an enum of this module", 2)
    end
    local e = {}
    for _, v in ipairs(t.values or {}) do
        e[v[1]] = v[2]
        if e[v[2]] == nil then
            e[v[2]] = v[1]
        end
    end
    return e
end

-- The member description of `field` in type `name`: { name, offset, cpp, bitpos, bits, unit = ... }
function bindings:field(name, field)
    local t = self:info(name)
    for _, f in ipairs(t and t.fields or {}) do
        if f[1] == field or f.cpp_name == field then
            return f
        end
    end
end

-- Bitfields LuaJIT cannot declare (in a 64-bit unit, across bit 32) are read and written here:
-- bindings:getbits(object, type, field) / bindings:setbits(object, type, field, value)
local function unit_of(self, obj, name, field)
    local f = self:field(name, field)
    if f == nil or f[4] == nil then
        fail(string.format("%s.%s is not a bitfield", tostring(name), tostring(field)), 3)
    end
    local p = ffi.cast("uint8_t *", obj) + f[2]
    return ffi.cast("uint64_t *", p), f[4], f[5]
end

function bindings:getbits(obj, name, field)
    need_ffi(2)
    local u, pos, n = unit_of(self, obj, name, field)
    local bit = require("bit")
    local v = bit.rshift(u[0], pos)
    return tonumber(bit.band(v, bit.lshift(ffi.cast("uint64_t", 1), n) - 1))
end

function bindings:setbits(obj, name, field, value)
    need_ffi(2)
    local u, pos, n = unit_of(self, obj, name, field)
    local bit = require("bit")
    local mask = bit.lshift(bit.lshift(ffi.cast("uint64_t", 1), n) - 1, pos)
    u[0] = bit.bor(bit.band(u[0], bit.bnot(mask)), bit.band(bit.lshift(ffi.cast("uint64_t", value), pos), mask))
end

-- bindings:cast(object, base) -> a pointer to the base class subobject of `object` (a pointer to a
-- class of this module, given as cdata; its type is told by `from`, default its ctype's name)
function bindings:cast(obj, base, from)
    need_ffi(2)
    local tname = from
    if tname == nil then
        tname = tostring(ffi.typeof(obj)):match("^ctype<struct ([%w_]+) %*>$") or tostring(ffi.typeof(obj)):match("^ctype<([%w_]+) %*>$")
    end
    local t = tname and self:info(tname)
    if t == nil then
        fail("cast: say what the object is (from)", 2)
    end
    local b = self:cname(base)
    local off
    if b == tname then
        off = 0
    else
        for _, x in ipairs(t.bases or {}) do
            if x[1] == b then
                off = x[2]
                break
            end
        end
    end
    if off == nil then
        fail(string.format("%s is not a base of %s", tostring(base), tostring(tname)), 2)
    end
    return ffi.cast(self:ptr(b), ffi.cast("uint8_t *", obj) + off)
end

-- bindings:functions(name) -> the declarations of a function (overloads, folded copies)
function bindings:functions(name)
    return self.module.functions[name]
end

-- Picks one declaration: `which` is an index, the function's RVA in the module's build, or a
-- declaration / C++ signature; without it, the only one (or several that are the same).
function bindings:func(name, which)
    local list = self.module.functions[name]
    if list == nil then
        return nil, "no declaration of " .. tostring(name)
    end
    if which == nil then
        local first = list[1]
        for i = 2, #list do
            if list[i].decl ~= first.decl or list[i].this_adjust ~= first.this_adjust then
                return nil, string.format("%s has %d declarations, choose one (index, rva or signature)", name, #list)
            end
        end
        return first
    end
    if type(which) == "number" then
        if which >= 1 and which <= #list and which % 1 == 0 and which < 0x1000 then
            return list[which]
        end
        for _, d in ipairs(list) do
            if d.rva == which then
                return d
            end
        end
        return nil, string.format("%s: no declaration at rva 0x%x", name, which)
    end
    for _, d in ipairs(list) do
        if d.decl == which or d.cpp == which then
            return d
        end
    end
    return nil, string.format("%s: no declaration %s", name, tostring(which))
end

-- The ctype of a declaration's function pointer, with its types declared.
function bindings:fntype(name, which)
    need_ffi(2)
    local d, err = self:func(name, which)
    if d == nil then
        fail(err, 2)
    end
    local ct = self._ctypes[d]
    if ct == nil then
        local out = batch()
        for _, dep in ipairs(d.deps) do
            collect(self, dep, true, out, 0)
        end
        for _, r in ipairs(d.refs) do
            collect(self, r, false, out, 0)
        end
        flush(out)
        ct = ffi.typeof(d.decl)
        self._ctypes[d] = ct
    end
    return ct, d
end

local function to_address(a)
    if type(a) == "number" then
        return a
    end
    if type(a) == "cdata" then
        return a
    end
    if type(a) == "userdata" then
        return a -- light userdata: ffi.cast takes it
    end
    fail("address expected, got " .. type(a), 3)
end

-- A function that calls `f` through the interpreter, never from a compiled trace: LuaJIT's C++
-- exception interoperability does not extend to FFI calls inside compiled code. Errors (and C++
-- exceptions, as "C++ exception") then reach the caller's pcall.
local function protect(f)
    local function call(...)
        return f(...)
    end
    if jit ~= nil then
        jit.off(call)
    end
    return call
end
M.protect = protect

-- bindings:fn(name, address [, which [, options]]) -> a typed function pointer (cdata) for the
-- function at `address` (in this process), and its declaration.
--   options.protect: true wraps it in a Lua function that is never compiled (see protect);
--   default: the load options', for functions that may throw ("yes" or "maybe") when it is "throws".
function bindings:fn(name, address, which, options)
    need_ffi(2)
    local ct, d = self:fntype(name, which)
    local f = ffi.cast(ct, to_address(address))
    local p = (options and options.protect)
    if p == nil then
        p = self._options.protect
    end
    if p == true or (p == "throws" and (d.throws == "yes" or d.throws == "maybe" or d.throws == "unknown")) then
        return protect(f), d
    end
    return f, d
end

local vtable_ptr, deleting_ct = nil, nil

-- bindings:vfn(object, name [, which]) -> function pointer, this: the virtual method from the
-- object's vtable, with the pointer to pass as `this` (the object, or its subobject that holds the
-- vfptr). For a destructor it is the deleting destructor: fn(this, flags), flags 1 frees the memory.
function bindings:vfn(obj, name, which)
    need_ffi(2)
    local d, err = self:func(name, which)
    if d == nil then
        fail(err, 2)
    end
    local v = d.virtual
    if v == nil then
        fail(name .. " is not virtual (or its slot is unknown)", 2)
    end
    vtable_ptr = vtable_ptr or ffi.typeof("void ***")
    local this = ffi.cast("uint8_t *", obj) + v.vfptr
    local vt = ffi.cast(vtable_ptr, this)[0]
    if d.kind == "dtor" or name:find("deleting destructor'", 1, true) then
        -- the slot holds the deleting destructor (or an adjustor thunk to it)
        deleting_ct = deleting_ct or ffi.typeof("void *(*)(void *, uint32_t)")
        return ffi.cast(deleting_ct, vt[v.slot]), ffi.cast("void *", this)
    end
    local ct = self:fntype(name, which)
    local f = ffi.cast(ct, vt[v.slot])
    -- the slot's function takes the subobject that holds the vfptr; give it the declared type
    local tp = (d.this and (d.this_adjust or 0) == v.vfptr) and self:ptr(d.this) or nil
    if tp == nil then
        return f, this -- the declaration's `this` type does not describe this subobject: pass bytes
    end
    return f, ffi.cast(tp, this)
end

-- bindings:vcall(object, name, ...) calls the virtual method on the object (overloads: give
-- `which` with vfn instead).
function bindings:vcall(obj, name, ...)
    local f, this = self:vfn(obj, name)
    return f(this, ...)
end

function bindings:__tostring()
    local b = self.build
    return string.format("fnmatch.ffi bindings (%s)", b and (b.id .. " " .. b.version) or tostring(self.module.pdb and self.module.pdb.file))
end

if fnmatch ~= nil then
    fnmatch.ffi = M
end
return M
